from __future__ import annotations

import os
from datetime import datetime
from typing import TYPE_CHECKING

from buvis.pybase.result import FatalError

from backup.capabilities import CAPABILITIES
from backup.config import effective_excludes
from backup.step_result import PlanEntry, StepResult

if TYPE_CHECKING:
    from collections.abc import Iterator

    from backup.config import BackupConfig, BackupInstance

__all__ = ["Runner"]


class Runner:
    """Execute selected backup instances, yielding a :class:`StepResult` per step.

    Each instance invokes its registered capability with the instance's ``with:``
    inputs plus the runtime context the capability needs: the resolved instance
    ``excludes`` list, the instance ``label``, and the ``dry_run`` flag. Under
    ``dry_run`` the capability itself previews (walks + reports) without writing.
    """

    def __init__(self: Runner, cfg: BackupConfig, *, dry_run: bool = False) -> None:
        self._cfg = cfg
        self._dry_run = dry_run

    def run(self: Runner, selected: list[tuple[str, BackupInstance]]) -> Iterator[StepResult]:
        now = datetime.now()
        entries = self._plan(selected, now)
        for (name, instance), entry in zip(selected, entries, strict=True):
            if entry.status == "fail":
                yield StepResult(name, success=False, message=entry.reason)
            else:
                yield from self._run_instance(name, instance, now)

    def plan(self: Runner, selected: list[tuple[str, BackupInstance]]) -> list[PlanEntry]:
        return self._plan(selected, datetime.now())

    def _plan(self: Runner, selected: list[tuple[str, BackupInstance]], now: datetime) -> list[PlanEntry]:
        entries = []
        keys: list[str | None] = []
        outputs: dict[str, list[str]] = {}
        for name, instance in selected:
            capability = CAPABILITIES.get(instance.use)
            key: str | None = None
            if capability is None:  # pragma: no cover - load_config validates this
                entry = PlanEntry(name, "", "", "fail", f"unknown capability '{instance.use}'", False)
            else:
                call_kwargs: dict[str, object] = {
                    **instance.with_,
                    "label": name,
                    "excludes": list(effective_excludes(self._cfg, instance)),
                    "now": now,
                }
                try:
                    entry = capability.plan(**call_kwargs)
                except FatalError:
                    raise
                except Exception as exc:
                    # keep the configured output so duplicate detection still sees it
                    # (resolved with the run-wide timestamp, like the capability does)
                    configured = now.strftime(str(instance.with_.get("out", "")))
                    entry = PlanEntry(name, "", configured, "fail", f"{name} failed: {exc}", False)
                if entry.out:
                    key = os.path.normpath(os.path.expanduser(entry.out))
                    outputs.setdefault(key, []).append(name)
            entries.append(entry)
            keys.append(key)

        for index, (entry, out) in enumerate(zip(entries, keys, strict=True)):
            if out is not None and len(outputs[out]) > 1:
                names = outputs[out]
                others = ", ".join(sorted(name for name in names if name != entry.label))
                entries[index] = entry._replace(
                    out=out,
                    status="fail",
                    reason=f"output '{out}' is also the output of '{others}'",
                )
        return entries

    def _run_instance(self: Runner, name: str, instance: BackupInstance, now: datetime) -> Iterator[StepResult]:
        capability = CAPABILITIES[instance.use]

        call_kwargs: dict[str, object] = {
            **instance.with_,
            "label": name,
            "excludes": list(effective_excludes(self._cfg, instance)),
            "dry_run": self._dry_run,
            "now": now,
        }
        try:
            yield from capability.run(**call_kwargs)
        except FatalError:
            raise
        except Exception as exc:
            yield StepResult(name, success=False, message=f"{name} failed: {exc}")

from __future__ import annotations

import tarfile
from datetime import datetime
from pathlib import Path
from typing import TYPE_CHECKING

import pytest
from buvis.pybase.result import FatalError

from backup.config import BackupConfig
from backup.runner import Runner

if TYPE_CHECKING:
    from os import stat_result

    from pytest_mock import MockerFixture


def _config(tmp_path: Path, outputs: dict[str, Path]) -> BackupConfig:
    instances = {}
    for name, out in outputs.items():
        source = tmp_path / "sources" / name
        source.mkdir(parents=True)
        (source / "tiny.txt").write_bytes(name.encode())
        instances[name] = {"use": "tar-archive", "with": {"source": str(source), "out": str(out)}}
    return BackupConfig.model_validate({"instances": instances})


def _fail_metadata(monkeypatch: pytest.MonkeyPatch, errors: dict[Path, Exception]) -> None:
    real_stat = Path.stat

    def stat(path: Path, *, follow_symlinks: bool = True) -> stat_result:
        if path in errors:
            raise errors[path]
        return real_stat(path, follow_symlinks=follow_symlinks)

    monkeypatch.setattr(Path, "stat", stat)


def _assert_archive(out: Path, name: str) -> None:
    with tarfile.open(out, "r:gz") as archive:
        assert {member.name for member in archive.getmembers() if member.isfile()} == {f"{name}/tiny.txt"}
        member = archive.extractfile(f"{name}/tiny.txt")
        assert member is not None
        assert member.read() == name.encode()


@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
@pytest.mark.parametrize("error_type", [OSError, PermissionError, RuntimeError])
@pytest.mark.parametrize("metadata", ["source", "out"])
def test_runner_isolates_metadata_failures_and_preserves_independent_instances(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, mode: str, error_type: type[Exception], metadata: str
) -> None:
    names = ("before", "blocked", "blocked-copy", "second-blocked", "after")
    outputs = {name: tmp_path / "archives" / name / "daily.tar.gz" for name in names}
    cfg = _config(tmp_path, outputs)
    failed = ("blocked", "second-blocked")
    messages = {name: f"{name}: {metadata} metadata unavailable" for name in failed}
    targets = {name: tmp_path / "sources" / name if metadata == "source" else outputs[name] for name in failed}
    runner = Runner(cfg, dry_run=mode == "dry-run")
    with monkeypatch.context() as patch:
        _fail_metadata(patch, {targets[name]: error_type(messages[name]) for name in failed})
        selected = list(cfg.instances.items())
        results = runner.plan(selected) if mode == "plan" else list(runner.run(selected))
    assert [result.label for result in results] == list(names)
    for result in results:
        out = outputs[result.label]
        if result.label in failed:
            if mode == "plan":
                assert result.status == "fail"
                assert messages[result.label] in result.reason
            else:
                assert result.success is False
                assert result.skipped is False
                assert messages[result.label] in result.message
            assert not out.exists()
            assert not out.parent.exists()
        else:
            if mode == "plan":
                assert result.status == "run"
                assert result.source == str(tmp_path / "sources" / result.label)
                assert result.out == str(out)
            else:
                assert result.success is True
                assert result.skipped is False
                assert result.out_path == str(out)
            assert out.exists() is (mode == "run")
            assert out.parent.exists() is (mode == "run")
            if mode == "run":
                _assert_archive(out, result.label)


@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
@pytest.mark.parametrize("error_type", [OSError, PermissionError, RuntimeError])
@pytest.mark.parametrize("metadata", ["source", "out"])
def test_runner_rejects_every_duplicate_output_even_when_member_metadata_fails(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, mode: str, error_type: type[Exception], metadata: str
) -> None:
    shared = tmp_path / "shared.tar.gz"
    shared.write_bytes(b"keep existing archive")
    colliding = ("blocked", "peer", "another-peer")
    outputs = dict.fromkeys(colliding, shared)
    outputs["blocked-copy"] = tmp_path / "independent" / "shared.tar.gz"
    outputs["suffix-copy"] = tmp_path / "shared.tar.gz.copy"
    cfg = _config(tmp_path, outputs)
    target = tmp_path / "sources" / "blocked" if metadata == "source" else shared
    runner = Runner(cfg, dry_run=mode == "dry-run")
    with monkeypatch.context() as patch:
        _fail_metadata(patch, {target: error_type(f"blocked {metadata} metadata")})
        selected = list(cfg.instances.items())
        results = runner.plan(selected) if mode == "plan" else list(runner.run(selected))
    assert [result.label for result in results] == list(outputs)
    for result in results:
        if result.label in colliding:
            others = ", ".join(sorted(name for name in colliding if name != result.label))
            message = f"output '{shared}' is also the output of '{others}'"
            if mode == "plan":
                assert result.status == "fail"
                assert result.reason == message
            else:
                assert result.success is False
                assert result.skipped is False
                assert result.message == message
        else:
            if mode == "plan":
                assert result.status == "run"
                assert result.out == str(outputs[result.label])
            else:
                assert result.success is True
                assert result.out_path == str(outputs[result.label])
            assert outputs[result.label].exists() is (mode == "run")
            if mode == "run":
                _assert_archive(outputs[result.label], result.label)
    assert shared.read_bytes() == b"keep existing archive"
    assert (tmp_path / "independent").exists() is (mode == "run")


@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
@pytest.mark.parametrize("message", ["backup storage unavailable", "backup permission fatal"])
@pytest.mark.parametrize("metadata", ["source", "out"])
def test_runner_propagates_the_original_fatal_metadata_error(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, mode: str, message: str, metadata: str
) -> None:
    out = tmp_path / "notes.tar.gz"
    cfg = _config(tmp_path, {"notes": out})
    fatal = FatalError(message)
    target = tmp_path / "sources" / "notes" if metadata == "source" else out
    runner = Runner(cfg, dry_run=mode == "dry-run")
    with monkeypatch.context() as patch:
        _fail_metadata(patch, {target: fatal})
        with pytest.raises(FatalError) as raised:
            selected = list(cfg.instances.items())
            if mode == "plan":
                runner.plan(selected)
            else:
                list(runner.run(selected))
    assert raised.value is fatal
    assert str(raised.value) == message
    assert not out.exists()


@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
def test_runner_keeps_empty_selection_empty_without_planning_unselected_instances(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, mode: str
) -> None:
    outputs = {name: tmp_path / "archives" / f"{name}.tar.gz" for name in ("notes", "notes-copy")}
    cfg = _config(tmp_path, outputs)
    errors = {tmp_path / "sources" / name: FatalError(f"unselected {name}") for name in outputs}
    errors.update({out: FatalError(f"unselected output {name}") for name, out in outputs.items()})
    runner = Runner(cfg, dry_run=mode == "dry-run")
    with monkeypatch.context() as patch:
        _fail_metadata(patch, errors)
        results = runner.plan([]) if mode == "plan" else list(runner.run([]))
    assert results == []
    assert not (tmp_path / "archives").exists()
    for name, out in outputs.items():
        assert not out.exists()
        assert (tmp_path / "sources" / name / "tiny.txt").read_bytes() == name.encode()


@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
@pytest.mark.parametrize("error_type", [OSError, PermissionError, RuntimeError])
@pytest.mark.parametrize("now", [datetime(2026, 12, 31, 23, 59, 59), datetime(2027, 1, 1, 0, 0, 1)])
def test_runner_rejects_timestamp_output_collisions_when_source_metadata_fails(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    mocker: MockerFixture,
    mode: str,
    error_type: type[Exception],
    now: datetime,
) -> None:
    pattern = "archive-%Y%m%d-%H%M%S.tar.gz"
    shared = tmp_path / "colliding" / now.strftime(pattern)
    independent = tmp_path / "independent" / "archive.tar.gz"
    cfg = _config(
        tmp_path,
        {
            "stamped": tmp_path / "colliding" / pattern,
            "literal": shared,
            "independent": independent,
        },
    )
    clock = mocker.patch("backup.runner.datetime", autospec=True)
    clock.now.return_value = now
    fallback = mocker.patch("backup.capabilities.tar_archive.datetime", autospec=True)
    fallback.now.return_value = datetime(2001, 6, 7, 8, 9, 10)
    runner = Runner(cfg, dry_run=mode == "dry-run")
    with monkeypatch.context() as patch:
        _fail_metadata(patch, {tmp_path / "sources" / "stamped": error_type("stamped source metadata")})
        selected = list(cfg.instances.items())
        results = runner.plan(selected) if mode == "plan" else list(runner.run(selected))
    assert [result.label for result in results] == ["stamped", "literal", "independent"]
    for result in results[:2]:
        other = "literal" if result.label == "stamped" else "stamped"
        message = f"output '{shared}' is also the output of '{other}'"
        if mode == "plan":
            assert result.status == "fail"
            assert result.reason == message
            assert result.out == str(shared)
        else:
            assert result.success is False
            assert result.skipped is False
            assert result.message == message
    if mode == "plan":
        assert results[2].status == "run"
        assert results[2].out == str(independent)
    else:
        assert results[2].success is True
        assert results[2].skipped is False
        assert results[2].out_path == str(independent)
    assert not shared.parent.exists()
    assert independent.exists() is (mode == "run")
    assert independent.parent.exists() is (mode == "run")
    if mode == "run":
        _assert_archive(independent, "independent")

from __future__ import annotations

import tarfile
from typing import TYPE_CHECKING

import pytest
from buvis.pybase.result import FatalError

from backup.capabilities.tar_archive import TarArchive
from backup.config import BackupConfig
from backup.runner import Runner

if TYPE_CHECKING:
    from pathlib import Path

    from pytest_mock import MockerFixture

    from backup.step_result import PlanEntry, StepResult


def _source(root: Path, name: str) -> Path:
    source = root / name
    source.mkdir(parents=True)
    (source / "tiny.txt").write_bytes(name.encode())
    (source / "tiny.txt-copy").write_bytes(f"{name}-copy".encode())
    return source


def _invoke(interface: str, mode: str, values: dict[str, object]) -> list[PlanEntry | StepResult]:
    if interface == "capability":
        archive = TarArchive()
        if mode == "plan":
            return [archive.plan(label="selected", **values)]
        return list(archive.run(label="selected", dry_run=mode == "dry-run", **values))
    cfg = BackupConfig.model_validate({"instances": {"selected": {"use": "tar-archive", "with": values}}})
    runner = Runner(cfg, dry_run=mode == "dry-run")
    selected = list(cfg.instances.items())
    return runner.plan(selected) if mode == "plan" else list(runner.run(selected))


def _assert_archive(out: Path, name: str) -> None:
    with tarfile.open(out, "r:gz") as archive:
        files = {member.name for member in archive.getmembers() if member.isfile()}
        assert files == {f"{name}/tiny.txt", f"{name}/tiny.txt-copy"}
        for filename, payload in (("tiny.txt", name), ("tiny.txt-copy", f"{name}-copy")):
            member = archive.extractfile(f"{name}/{filename}")
            assert member is not None
            assert member.read() == payload.encode()


def _snapshot(root: Path) -> dict[str, bytes | None]:
    return {str(path.relative_to(root)): path.read_bytes() if path.is_file() else None for path in root.rglob("*")}


@pytest.mark.parametrize("interface", ["capability", "runner"])
@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
@pytest.mark.parametrize("name", ["notes", "photos"])
def test_empty_engine_matches_omitted_python_engine(tmp_path: Path, interface: str, mode: str, name: str) -> None:
    source = _source(tmp_path / "sources", name)
    out = tmp_path / "archives" / f"{name}.tar.gz"
    values = {"source": str(source), "out": str(out)}
    omitted = _invoke(interface, "plan", values)
    results = _invoke(interface, mode, {**values, "engine": ""})

    assert len(omitted) == len(results) == 1
    assert omitted[0].status == "run"
    result = results[0]
    assert result.label == "selected"
    if mode == "plan":
        assert result == omitted[0]
        assert result.source == str(source)
        assert result.out == str(out)
        assert result.replaces is False
    else:
        assert result.success is True
        assert result.skipped is False
        assert result.out_path == str(out)
    assert out.exists() is (mode == "run")
    assert out.parent.exists() is (mode == "run")
    if mode == "run":
        _assert_archive(out, name)
    assert (source / "tiny.txt").read_bytes() == name.encode()
    assert (source / "tiny.txt-copy").read_bytes() == f"{name}-copy".encode()


@pytest.mark.parametrize("interface", ["capability", "runner"])
@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
@pytest.mark.parametrize(("key", "message"), [("source", "no source configured"), ("out", "no out path configured")])
@pytest.mark.parametrize("existing", [False, True])
def test_empty_paths_fail_without_using_cwd_or_changing_artifacts(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, interface: str, mode: str, key: str, message: str, existing: bool
) -> None:
    source = _source(tmp_path / "sources", "notes")
    cwd = _source(tmp_path, "working")
    monkeypatch.chdir(cwd)
    out = tmp_path / "archives" / "notes.tar.gz"
    if existing:
        out.parent.mkdir()
        out.write_bytes(b"keep existing archive")
    values = {"source": str(source), "out": str(out), key: ""}
    before = _snapshot(tmp_path)

    results = _invoke(interface, mode, values)

    assert len(results) == 1
    result = results[0]
    assert result.label == "selected"
    if mode == "plan":
        assert result.status == "fail"
        assert result.reason == message
        if key == "out":
            assert result.out == ""
            assert result.replaces is False
    else:
        assert result.success is False
        assert result.skipped is False
        assert result.message == message
    assert _snapshot(tmp_path) == before


def _mixed_config(tmp_path: Path) -> tuple[BackupConfig, Path]:
    shared = tmp_path / "shared.tar.gz"
    shared.write_bytes(b"preserve duplicate archive")
    values = {}
    for name in ("empty", "empty-copy", "missing", "missing-copy", "same", "same-copy", "notes", "notes-copy"):
        source = _source(tmp_path / "sources", name)
        out = str(tmp_path / "outputs" / f"{name}.tar.gz")
        if name in {"empty", "empty-copy"}:
            out = ""
        elif name in {"same", "same-copy"}:
            out = str(shared)
        values[name] = {"source": "" if name in {"missing", "missing-copy"} else str(source), "out": out}
    cfg = BackupConfig.model_validate(
        {"instances": {name: {"use": "tar-archive", "with": value} for name, value in values.items()}}
    )
    return cfg, shared


@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
def test_runner_keeps_missing_inputs_distinct_from_collisions_and_executes_independent_instances(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, mode: str
) -> None:
    cfg, shared = _mixed_config(tmp_path)
    cwd = _source(tmp_path, "working")
    before_cwd = _snapshot(cwd)
    monkeypatch.chdir(cwd)
    runner = Runner(cfg, dry_run=mode == "dry-run")
    selected = list(cfg.instances.items())

    results = runner.plan(selected) if mode == "plan" else list(runner.run(selected))

    assert [result.label for result in results] == list(cfg.instances)
    for result in results:
        name = result.label
        if name in {"notes", "notes-copy"}:
            assert result.status == "run" if mode == "plan" else result.success is True
            out = tmp_path / "outputs" / f"{name}.tar.gz"
            assert out.exists() is (mode == "run")
            if mode == "run":
                _assert_archive(out, name)
            continue
        message = "no out path configured" if name in {"empty", "empty-copy"} else "no source configured"
        if name in {"same", "same-copy"}:
            other = "same-copy" if name == "same" else "same"
            message = f"output '{shared}' is also the output of '{other}'"
        assert result.status == "fail" if mode == "plan" else result.success is False
        assert (result.reason if mode == "plan" else result.message) == message
    expected = {shared}
    if mode == "run":
        expected |= {tmp_path / "outputs" / f"{name}.tar.gz" for name in ("notes", "notes-copy")}
    assert set(tmp_path.rglob("*.tar.gz")) == expected
    assert shared.read_bytes() == b"preserve duplicate archive"
    assert _snapshot(cwd) == before_cwd
    assert (tmp_path / "outputs").exists() is (mode == "run")


@pytest.mark.parametrize("interface", ["capability", "runner"])
@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
@pytest.mark.parametrize("engine", ["python-tarfile-copy", "copy-python-tarfile"])
def test_engine_lookalikes_remain_rejected_without_archive_effects(
    tmp_path: Path, interface: str, mode: str, engine: str
) -> None:
    source = _source(tmp_path / "sources", "photos")
    out = tmp_path / "archives" / "photos.tar.gz"
    out.parent.mkdir()
    out.write_bytes(b"preserve rejected engine archive")
    before = _snapshot(tmp_path)

    results = _invoke(interface, mode, {"source": str(source), "out": str(out), "engine": engine})

    assert len(results) == 1
    assert results[0].label == "selected"
    assert results[0].status == "fail" if mode == "plan" else results[0].success is False
    message = results[0].reason if mode == "plan" else results[0].message
    assert f"unknown engine '{engine}'" in message
    assert _snapshot(tmp_path) == before


@pytest.mark.parametrize("interface", ["capability", "runner"])
@pytest.mark.parametrize("message", ["archive storage unavailable", "archive permission denied"])
def test_fatal_archive_errors_propagate_with_empty_default_engine(
    tmp_path: Path, mocker: MockerFixture, interface: str, message: str
) -> None:
    source = _source(tmp_path / "sources", "notes")
    out = tmp_path / "notes.tar.gz"
    mocker.patch("tarfile.open", autospec=True, side_effect=FatalError(message))

    with pytest.raises(FatalError, match=message):
        _invoke(interface, "run", {"source": str(source), "out": str(out), "engine": ""})

    assert not out.exists()
    assert (source / "tiny.txt").read_bytes() == b"notes"
    assert (source / "tiny.txt-copy").read_bytes() == b"notes-copy"


@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
def test_runner_empty_selection_has_no_archive_effects(tmp_path: Path, mode: str) -> None:
    source = _source(tmp_path / "sources", "unselected")
    cfg = BackupConfig.model_validate(
        {"instances": {"unselected": {"use": "tar-archive", "with": {"source": str(source), "out": ""}}}}
    )
    before = _snapshot(tmp_path)
    runner = Runner(cfg, dry_run=mode == "dry-run")

    results = runner.plan([]) if mode == "plan" else list(runner.run([]))

    assert results == []
    assert _snapshot(tmp_path) == before

